@public @buseventtype create schema MyEvent as (in1 string, in2 int);
create schema MySchema as (col1 string, col2 int);
@name('create') @public create window MyInfraNWC#keepall as MySchema;
on SupportBean_A delete from MyInfraNWC;
on MyEvent me merge MyInfraNWC mw when not matched and me.in1 like "A%" then insert(col1, col2) select me.in1, me.in2 when not matched and me.in1 like "B%" then insert select me.in1 as col1, me.in2 as col2 when matched and me.in1 like "C%" then update set col1='Z', col2=-1 when not matched then insert select "x" || me.in1 || "x" as col1, me.in2 * -1 as col2;

